namespace Orders.Domain;

public class Order
{
    // Generated by the shop when the customer reaches checkout, so placing the same order twice
    // (a double click, a retry after a timeout) finds the first one rather than creating another.
    public Guid Id { get; set; }
    public int CustomerId { get; set; }
    public string CustomerEmail { get; set; } = "";
    public string CustomerFirstName { get; set; } = "";
    public string CustomerLastName { get; set; } = "";
    public OrderStatus Status { get; set; }

    // Copies of the customer's address and card as they were at checkout, so later edits in
    // Profile don't change a placed order.
    public OrderAddress DeliveryAddress { get; set; } = new();
    public int PaymentCardId { get; set; }
    public string CardBrand { get; set; } = "";
    public string CardLast4 { get; set; } = "";

    public decimal Subtotal { get; set; }
    public decimal Shipping { get; set; }
    public decimal Total { get; set; }
    public string Currency { get; set; } = "AUD";

    // Set when PaymentGateway reports the card was charged.
    public string? PaymentTransactionId { get; set; }
    public DateTime? PaidAt { get; set; }

    // Set when the warehouse reports the order dispatched.
    public DateTime? CompletedAt { get; set; }

    public DateTime PlacedAt { get; set; }
    public DateTime UpdatedAt { get; set; }

    public List<OrderLine> Lines { get; set; } = [];

    // Returns false if the payment was already applied (a redelivered event), so nothing changes.
    public bool ApplyPayment(string transactionId, DateTime paidAt)
    {
        if (Status != OrderStatus.Pending)
            return false;

        Status = OrderStatus.Paid;
        PaymentTransactionId = transactionId;
        PaidAt = paidAt;
        UpdatedAt = DateTime.UtcNow;
        return true;
    }

    // Returns false if the order isn't waiting on the warehouse (e.g. already completed).
    public bool Complete(DateTime completedAt)
    {
        if (Status != OrderStatus.Paid)
            return false;

        Status = OrderStatus.Completed;
        CompletedAt = completedAt;
        UpdatedAt = DateTime.UtcNow;
        return true;
    }
}

public enum OrderStatus
{
    Pending,
    Paid,
    Completed,
}
